import{_ as t,o,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UC — Update Trend Flow (Lean LLM-label pipeline T0→T7)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ai-features/update-trend-flow/spec.md","filePath":"feature/ai-features/update-trend-flow/spec.md"}'),i={name:"feature/ai-features/update-trend-flow/spec.md"};function r(d,e,c,l,h,s){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="uc-—-update-trend-flow-lean-llm-label-pipeline-t0→t7" tabindex="-1">UC — Update Trend Flow (Lean LLM-label pipeline T0→T7) <a class="header-anchor" href="#uc-—-update-trend-flow-lean-llm-label-pipeline-t0→t7" aria-label="Permalink to &quot;UC — Update Trend Flow (Lean LLM-label pipeline T0→T7)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>Internal — hỗ trợ FR 3.7.1 (View Trending Topics)</td></tr><tr><td>Feature</td><td>Update Trend Flow — thay pipeline cũ (BM25 + graph) bằng lean LLM label</td></tr><tr><td>Domain</td><td>AI Features (FR 3.7) — pipeline AI-05</td></tr><tr><td>Role</td><td>SYSTEM (backend pipeline; Streamlit demo để test)</td></tr><tr><td>Version</td><td>2.0 (2026-10-02)</td></tr><tr><td>Trạng thái tài liệu</td><td>Đã code — docs viết lại khớp code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Thay pipeline trend cũ (8 tầng: T3 Topic dict, T4 BM25 spike, T5 engagement, T6 graph Neo4j) bằng flow <strong>lean 6 tầng</strong> chạy AI trên HuggingFace, không cần Neo4j graph ở khâu phát hiện trend. Nhãn do PhoBERT 3 model gộp 1 pass, fallback Gemini. Thêm <strong>emotion breakdown %</strong> (softmax 6 lớp) thay cho 1 nhãn argmax đơn.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là hệ thống trend pipeline, tôi muốn gán nhãn topic/emotion/entity/keyphrase bằng LLM và tính dư luận (sentiment comment) cùng emotion % cho từng trend, để kết quả trend phản ánh đúng chủ đề + sắc thái cảm xúc thay vì 1 nhãn cứng.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li><strong>AC-1 (Flow):</strong> Pipeline chạy đúng <code>T0 Ingestion → T1 BotFilter → T2 LLM Label → T4 Burst → T5 Sentiment → T7 Fusion</code> (không còn T3 topic-dict / T6 graph).</li><li><strong>AC-2 (Label):</strong> T2 gán topic (12 lớp) + emotion (6 lớp) + NER (5 loại entity) <ul><li>keyphrase cho mỗi post, PhoBERT là chính, thiếu nhánh nào thì Gemini bù (env key).</li></ul></li><li><strong>AC-3 (Emotion %):</strong> T2 trả <code>emotion_dist</code> = softmax prob 6 lớp cho mỗi post; T7 gộp trung bình theo cluster → <code>emotion_dist</code> của trend.</li><li><strong>AC-4 (Burst):</strong> T4 tính burst = f(density + velocity + coverage + engage), ra <code>anomaly_scores</code> + <code>time_series</code> (trajectory ngày).</li><li><strong>AC-5 (Sentiment):</strong> T5 tính dư luận = comment emotion (PhoBERT trên comment) + reaction ratio (FB) + share/like ratio → <code>moods</code> từng post.</li><li><strong>AC-6 (Fusion):</strong> T7 cluster keyphrase → CandidateTrend, gán topic + emotion (author) + mood (dư luận) + emotion_dist → <code>brand_risk</code> + <code>status</code> (new/rising/peaking/declining).</li><li><strong>AC-7 (Parity):</strong> Demo (<code>trend-pipeline</code>) và production (<code>brandhub-ai-service</code>) cùng flow + cùng field, chỉ khác model ref (local dir vs HF repo) và Gemini client.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Không có UI người dùng cuối. Demo: <code>streamlit run ui.py</code> (bảng xếp hạng + emotion breakdown từng trend).</li></ul><h2 id="_5-api-contract-production" tabindex="-1">5. API Contract (production) <a class="header-anchor" href="#_5-api-contract-production" aria-label="Permalink to &quot;5. API Contract (production)&quot;">​</a></h2><p><code>NormalizeTrendResponse.candidates[]</code> mỗi trend thêm field <code>emotion_dist</code> (<code>{label: %}</code> 6 lớp), bên cạnh <code>topic</code>, <code>emotion</code>, <code>mood</code>, <code>brand_risk</code>, <code>status</code>.</p><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>PhoBERT không load được (thiếu torch/model) → <code>predict_*</code> trả None → fallback Gemini; không có key Gemini → nhãn None, pipeline vẫn chạy không crash.</li><li><code>emotion_probs</code> chỉ có khi PhoBERT chạy; post dùng Gemini fallback → <code>None</code>, T7 bỏ qua post đó khi gộp <code>emotion_dist</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Post không có comment → T5 mood fallback reaction ratio / share-like; vẫn <code>neutral</code>.</li><li>Cluster 1 post → <code>emotion_dist</code> = chính softmax post đó.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Pipeline lean chạy end-to-end ra trend, mỗi trend có topic/emotion/mood/emotion_dist.</li><li>Demo + production cùng output schema.</li><li>Smoke test production pass (sau khi có đủ deps torch/groq).</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Neo4j graph virality (bỏ ở khâu phát hiện; GraphRAG tầng 4 vẫn riêng).</li><li>Tune ngưỡng mood / class balance (neutral vẫn áp đảo — tune sau).</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../BA/06-ai-features.html">06-ai-features.md</a></p>',22)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
